    "author": "Rashi (1040–1105)",
    "text": "«Și a fost înțărcat.» La sfârșitul a douăzeci și patru de luni.<br><br>«Un ospăț mare.» Căci erau acolo marii generației: Sem, Eber și Abimelec."
