    "text": "«Nu fi mâhnit etc.: tot ceea ce îți va spune Sara.» Să nu-ți pară rău ce va spune în privința tânărului și a slujnicei, să-i izgonești cu semnele robiei, cum a spus: „I le-a pus pe umăr etc.”<br><br>«Ascultă de glasul ei.» Căci pe drept a spus să faci așa.<br><br>«Căci prin Isaac îți va fi socotită sămânța.» Iar Ismael și fiii lui îi vor fi sclavi, căci prin Isaac îți va fi socotită sămânța, și nu prin el."
