    "source": "Textul Masoretic (ebraică)",
    "original": "וַתֵּלֶךְ וַתֵּשֶׁב לָהּ מִנֶּגֶד הַרְחֵק כִּמְטַחֲוֵי קֶשֶׁת כִּי אָמְרָה אַל־אֶרְאֶה בְּמוֹת הַיָּלֶד וַתֵּשֶׁב מִנֶּגֶד וַתִּשָּׂא אֶת־קֹלָהּ וַתֵּבְךְּ",
    "translation": "„A mers și s-a așezat departe, la distanță, la câteva aruncături de arc, căci spunea: „Să nu văd moartea copilului!” S-a așezat deoparte, și-a ridicat glasul și a plâns.” — traducerea rabinului Rosen.",
    "note": ""
